            decodedRequests: number;
            rawRequests: number;
            enqueuedRequests: number;
            pendingRequests: number;
            claimedRequests: number;
            injections: number;
            decodedRequestId?: string;
            rawRequestId?: string;
            targetSessionId?: string;
